<div class="pagehead"><div><span class="badge">RF-02 · Reservar libros</span><h1>Mis reservas</h1></div><a class="button secondary" href="<?=url('books')?>">Volver al catálogo</a></div><?php if(isset($_GET['ok'])): ?><p class="notice"><?=e($_GET['ok']==='1'?'Operación realizada correctamente.':'No se pudo realizar la operación.')?></p><?php endif;?><div class="panel"><table><thead><tr><th>Libro</th><th>Fecha</th><th>Estado</th><th>Acción</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=e($r['title'])?></td><td><?=e($r['reserved_at'])?></td><td><?=e($r['status'])?></td><td><?php if($r['status']==='active'): ?><form method="post" action="<?=url('cancel')?>"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button class="small">Cancelar</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table><?php if(!$rows): ?><p>Aún no tienes reservas.</p><?php endif;?></div>
